pub proof fn lemma_vrs_reconcile_core_never_returns_external_request(
    v_replica_set: VReplicaSetView,
    resp_o: Option<ResponseView<VoidERespView>>,
    state: VReplicaSetReconcileState,
)
ensures
    match reconcile_core(v_replica_set, resp_o, state).1 {
        Some(RequestView::ExternalRequest(_)) => false,
        _ => true,
    }
{
    // The VReplicaSet reconciler uses only Kubernetes API requests and never constructs ExternalRequest.
    // Therefore, reconcile_core's request output can only be a Kubernetes request or None.
    assert(reconcile_core(v_replica_set, resp_o, state).1 is None
        || reconcile_core(v_replica_set, resp_o, state).1.unwrap().is_KRequest());
}

